51	// ViewChanger is responsible for running the view change protocol.
52	type ViewChanger struct {
53		// Configuration
54		SelfID             uint64
55		NodesList          []uint64
56		N                  uint64
57		f                  int
58		quorum             int
59		SpeedUpViewChange  bool
60		LeaderRotation     bool
61		DecisionsPerLeader uint64
62	
63		Logger       api.Logger
64		Comm         Comm
65		Signer       api.Signer
66		Verifier     api.Verifier
67		Application  api.Application
68		Synchronizer Synchronizer
69	
70		Checkpoint *types.Checkpoint
71		InFlight   *InFlightData
72		State      State
73	
74		Controller    ViewController
75		RequestsTimer RequestsTimer
76		Pruner        Pruner
77	
78		// for the in flight proposal view
79		ViewSequences      *atomic.Value
80		inFlightDecideChan chan struct{}
81		inFlightSyncChan   chan struct{}
82		inFlightView       *View
83		inFlightViewLock   sync.RWMutex
84	
85		Ticker              <-chan time.Time
86		lastTick            time.Time
87		ResendTimeout       time.Duration
88		lastResend          time.Time
89		ViewChangeTimeout   time.Duration
90		startViewChangeTime time.Time
91		checkTimeout        bool
92		backOffFactor       uint64
93	
94		// Runtime
95		MetricsViewChange         *api.MetricsViewChange
96		MetricsBlacklist          *api.MetricsBlacklist
97		MetricsView               *api.MetricsView
98		Restore                   chan struct{}
99		InMsqQSize                int
100		incMsgs                   chan *incMsg
101		viewChangeMsgs            *voteSet
102		viewDataMsgs              *voteSet
103		nvs                       *nextViews
104		realView                  uint64
105		currView                  uint64
106		nextView                  uint64
107		startChangeChan           chan *change
108		informChan                chan uint64
109		committedDuringViewChange *protos.ViewMetadata
110	
111		stopOnce sync.Once
112		stopChan chan struct{}
113		vcDone   sync.WaitGroup
114	
115		ControllerStartedWG sync.WaitGroup
116	}
117	
118	// Start the view changer
119	func (v *ViewChanger) Start(startViewNumber uint64) {
120		v.incMsgs = make(chan *incMsg, v.InMsqQSize)
121		v.startChangeChan = make(chan *change, 2)
122		v.informChan = make(chan uint64, 1)
123	
124		if v.MetricsViewChange == nil {
125			v.MetricsViewChange = api.NewMetricsViewChange(&disabled.Provider{})
126		}
127	
128		v.quorum, v.f = computeQuorum(v.N)
129	
130		v.stopChan = make(chan struct{})
131		v.stopOnce = sync.Once{}
132		v.vcDone.Add(1)
133	
134		v.setupVotes()
135	
136		v.nvs = &nextViews{}
137		v.nvs.clear()
138		// set without locking
139		v.currView = startViewNumber
140		v.realView = v.currView
141		v.nextView = v.currView
142		v.MetricsViewChange.CurrentView.Set(float64(v.currView))
143		v.MetricsViewChange.RealView.Set(float64(v.realView))
144		v.MetricsViewChange.NextView.Set(float64(v.nextView))
145	
146		v.lastTick = time.Now()
147		v.lastResend = v.lastTick
148	
149		v.backOffFactor = 1
150	
151		v.inFlightDecideChan = make(chan struct{})
152		v.inFlightSyncChan = make(chan struct{})
153	
154		go func() {
155			defer v.vcDone.Done()
156			v.ControllerStartedWG.Wait()
157			v.run()
158		}()
159	}
160	
161	func (v *ViewChanger) setupVotes() {
162		// view change
163		acceptViewChange := func(_ uint64, message *protos.Message) bool {
164			return message.GetViewChange() != nil
165		}
166		v.viewChangeMsgs = &voteSet{
167			validVote: acceptViewChange,
168		}
169		v.viewChangeMsgs.clear(v.N)
170	
171		// view data
172		acceptViewData := func(_ uint64, message *protos.Message) bool {
173			return message.GetViewData() != nil
174		}
175		v.viewDataMsgs = &voteSet{
176			validVote: acceptViewData,
177		}
178		v.viewDataMsgs.clear(v.N)
179	}
180	
181	func (v *ViewChanger) close() {
182		v.stopOnce.Do(
183			func() {
184				select {
185				case <-v.stopChan:
186					return
187				default:
188					close(v.stopChan)
189				}
190			},
191		)
192	}
193	
194	// Stop the view changer
195	func (v *ViewChanger) Stop() {
196		v.close()
197		v.vcDone.Wait()
198	}
199	
200	// HandleMessage passes a message to the view changer
201	func (v *ViewChanger) HandleMessage(sender uint64, m *protos.Message) {
202		msg := &incMsg{sender: sender, Message: m}
203		select {
204		case <-v.stopChan:
205			return
206		case v.incMsgs <- msg:
207		}
208	}
209	
210	func (v *ViewChanger) run() {
211		for {
212			select {
213			case <-v.stopChan:
214				return
215			case changeMsg := <-v.startChangeChan:
216				v.startViewChange(changeMsg)
217			case msg := <-v.incMsgs:
218				v.processMsg(msg.sender, msg.Message)
219			case now := <-v.Ticker:
220				v.lastTick = now
221				v.checkIfResendViewChange(now)
222				v.checkIfTimeout(now)
223			case info := <-v.informChan:
224				v.informNewView(info)
225			case <-v.Restore:
226				v.processViewChangeMsg(true)
227			}
228		}
229	}
230	
231	func (v *ViewChanger) getLeader() uint64 {
232		return getLeaderID(v.currView, v.N, v.NodesList, v.LeaderRotation, 0, v.DecisionsPerLeader, v.blacklist())
233	}
234	
235	func (v *ViewChanger) checkIfResendViewChange(now time.Time) {
236		nextTimeout := v.lastResend.Add(v.ResendTimeout)
237		if nextTimeout.After(now) { // check if it is time to resend
238			return
239		}
240		if v.checkTimeout { // during view change process
241			msg := &protos.Message{
242				Content: &protos.Message_ViewChange{
243					ViewChange: &protos.ViewChange{
244						NextView: v.nextView,
245					},
246				},
247			}
248			v.Comm.BroadcastConsensus(msg)
249			v.Logger.Debugf("Node %d resent a view change message with next view %d", v.SelfID, v.nextView)
250			v.lastResend = now // update last resend time, or at least last time we checked if we should resend
251		}
252	}
253	
254	func (v *ViewChanger) checkIfTimeout(now time.Time) bool {
255		if !v.checkTimeout {
256			return false
257		}
258		nextTimeout := v.startViewChangeTime.Add(v.ViewChangeTimeout * time.Duration(v.backOffFactor))
259		if nextTimeout.After(now) { // check if timeout has passed
260			return false
261		}
262		v.Logger.Debugf("Node %d got a view change timeout, the current view is %d", v.SelfID, v.currView)
263		v.checkTimeout = false // stop timeout for now, a new one will start when a new view change begins
264		v.backOffFactor++      // next timeout will be longer
265		// the timeout has passed, something went wrong, try sync and complain
266		v.Logger.Debugf("Node %d is calling sync because it got a view change timeout", v.SelfID)
267		v.Synchronizer.Sync()
268		v.StartViewChange(v.currView, false) // don't stop the view, the sync maybe created a good view
269		return true
270	}
271	
272	func (v *ViewChanger) processMsg(sender uint64, m *protos.Message) {
273		// viewChange message
274		if vc := m.GetViewChange(); vc != nil {
275			v.Logger.Debugf("Node %d is processing a view change message %v from %d with next view %d", v.SelfID, m, sender, vc.NextView)
276			v.nvs.registerNext(vc.NextView, sender)
277			// check view number
278			if vc.NextView == v.currView+1 { // accept view change only to immediate next view number
279				v.viewChangeMsgs.registerVote(sender, m)
280				v.processViewChangeMsg(false)
281				return
282			}
283			if v.nextView == v.currView+1 && // node has already started view change with last view
284				vc.NextView > v.realView &&
285				vc.NextView < v.currView+1 &&
286				v.nvs.sendRecv(vc.NextView, sender) {
287				// Let's help the lagging nodes.
288				msg := &protos.Message{
289					Content: &protos.Message_ViewChange{
290						ViewChange: &protos.ViewChange{
291							NextView: vc.NextView,
292						},
293					},
294				}
295				v.Comm.BroadcastConsensus(msg)
296				v.Logger.Warnf("Node %d got viewChange message %v from %d with view %d, expected view %d, help the lagging nodes", v.SelfID, m, sender, vc.NextView, v.currView+1)
297				return
298			}
299			v.Logger.Warnf("Node %d got viewChange message %v from %d with view %d, expected view %d", v.SelfID, m, sender, vc.NextView, v.currView+1)
300			return
301		}
302	
303		// viewData message
304		if vd := m.GetViewData(); vd != nil {
305			v.Logger.Debugf("Node %d is processing a view data message %s from %d", v.SelfID, MsgToString(m), sender)
306			if !v.validateViewDataMsg(vd, sender) {
307				return
308			}
309			v.viewDataMsgs.registerVote(sender, m)
310			v.processViewDataMsg()
311			return
312		}
313	
314		// newView message
315		if nv := m.GetNewView(); nv != nil {
316			v.Logger.Debugf("Node %d is processing a new view message %s from %d", v.SelfID, MsgToString(m), sender)
317			leader := v.getLeader()
318			if sender != leader {
319				v.Logger.Warnf("Node %d got newView message %v from %d, expected sender to be %d the next leader", v.SelfID, MsgToString(m), sender, leader)
320				return
321			}
322			v.processNewViewMsg(nv)
323		}
324	}
325	
326	// InformNewView tells the view changer to advance to a new view number
327	func (v *ViewChanger) InformNewView(view uint64) {
328		select {
329		case v.informChan <- view:
330		case <-v.stopChan:
331			return
332		}
333	}
334	
335	func (v *ViewChanger) informNewView(view uint64) {
336		if view < v.currView {
337			v.Logger.Debugf("Node %d was informed of view %d, but the current view is %d", v.SelfID, view, v.currView)
338			return
339		}
340		v.Logger.Debugf("Node %d was informed of a new view %d", v.SelfID, view)
341		v.currView = view
342		v.realView = v.currView
343		v.nextView = v.currView
344		v.MetricsViewChange.CurrentView.Set(float64(v.currView))
345		v.MetricsViewChange.RealView.Set(float64(v.realView))
346		v.MetricsViewChange.NextView.Set(float64(v.nextView))
347		v.nvs.clear()
348		v.viewChangeMsgs.clear(v.N)
349		v.viewDataMsgs.clear(v.N)
350		v.checkTimeout = false
351		v.backOffFactor = 1 // reset
352		v.RequestsTimer.RestartTimers()
353	}
354	
355	// StartViewChange initiates a view change
356	func (v *ViewChanger) StartViewChange(view uint64, stopView bool) {
357		select {
358		case v.startChangeChan <- &change{view: view, stopView: stopView}:
359		default:
360		}
361	}
362	
363	// StartViewChange stops current view and timeouts, and broadcasts a view change message to all
364	func (v *ViewChanger) startViewChange(change *change) {
365		if change.view < v.currView { // this is about an old view
366			v.Logger.Debugf("Node %d has a view change request with an old view %d, while the current view is %d", v.SelfID, change.view, v.currView)
367			return
368		}
369		if v.nextView == v.currView+1 {
370			v.Logger.Debugf("Node %d has already started view change with last view %d", v.SelfID, v.currView)
371			v.checkTimeout = true // make sure timeout is checked anyway
372			return
373		}
374		v.nextView = v.currView + 1
375		v.MetricsViewChange.NextView.Set(float64(v.nextView))
376		v.RequestsTimer.StopTimers()
377		msg := &protos.Message{
378			Content: &protos.Message_ViewChange{
379				ViewChange: &protos.ViewChange{
380					NextView: v.nextView,
381				},
382			},
383		}
384		v.Comm.BroadcastConsensus(msg)
385		v.Logger.Debugf("Node %d started view change, last view is %d", v.SelfID, v.currView)
386		if change.stopView {
387			v.Controller.AbortView(v.currView) // abort the current view when joining view change
388		}
389		v.startViewChangeTime = v.lastTick
390		v.checkTimeout = true
391	}
392	
393	func (v *ViewChanger) processViewChangeMsg(restore bool) {
394		if ((uint64(len(v.viewChangeMsgs.voted)) == uint64(v.f+1)) && v.SpeedUpViewChange) || restore { // join view change
395			v.Logger.Debugf("Node %d is joining view change, last view is %d", v.SelfID, v.currView)
396			v.startViewChange(&change{v.currView, true})
397		}
398		if (len(v.viewChangeMsgs.voted) < v.quorum-1) && !restore {
399			return
400		}
401		// send view data
402		if !v.SpeedUpViewChange {
403			v.Logger.Debugf("Node %d is joining view change, last view is %d", v.SelfID, v.currView)
404			v.startViewChange(&change{v.currView, true})
405		}
406		if !restore {
407			msgToSave := &protos.SavedMessage{
408				Content: &protos.SavedMessage_ViewChange{
409					ViewChange: &protos.ViewChange{
410						NextView: v.currView,
411					},
412				},
413			}
414			if err := v.State.Save(msgToSave); err != nil {
415				v.Logger.Panicf("Failed to save message to state, error: %v", err)
416			}
417		}
418		v.Controller.AbortView(v.currView) // before preparing the view data message abort the current view
419		v.currView = v.nextView
420		v.MetricsViewChange.CurrentView.Set(float64(v.currView))
421		v.viewChangeMsgs.clear(v.N)
422		v.viewDataMsgs.clear(v.N) // clear because currView changed
423		msg := v.prepareViewDataMsg()
424		leader := v.getLeader()
425		if leader == v.SelfID {
426			v.viewDataMsgs.registerVote(v.SelfID, msg)
427		} else {
428			v.Comm.SendConsensus(leader, msg)
429		}
430		v.Logger.Debugf("Node %d sent view data msg, with next view %d, to the new leader %d", v.SelfID, v.currView, leader)
431	}
432	
433	func (v *ViewChanger) prepareViewDataMsg() *protos.Message {
434		lastDecision, lastDecisionSignatures := v.Checkpoint.Get()
435		inFlight := v.getInFlight(lastDecision)
436		prepared := v.InFlight.IsInFlightPrepared()
437		vd := &protos.ViewData{
438			NextView:               v.currView,
439			LastDecision:           lastDecision,
440			LastDecisionSignatures: lastDecisionSignatures,
441			InFlightProposal:       inFlight,
442			InFlightPrepared:       prepared,
443		}
444		vdBytes := MarshalOrPanic(vd)
445		sig := v.Signer.Sign(vdBytes)
446		msg := &protos.Message{
447			Content: &protos.Message_ViewData{
448				ViewData: &protos.SignedViewData{
449					RawViewData: vdBytes,
450					Signer:      v.SelfID,
451					Signature:   sig,
452				},
453			},
454		}
455		return msg
456	}
457	
458	func (v *ViewChanger) getInFlight(lastDecision *protos.Proposal) *protos.Proposal {
459		inFlight := v.InFlight.InFlightProposal()
460		if inFlight == nil {
461			v.Logger.Debugf("Node %d's in flight proposal is not set", v.SelfID)
462			return nil
463		}
464		if inFlight.Metadata == nil {
465			v.Logger.Panicf("Node %d's in flight proposal metadata is not set", v.SelfID)
466		}
467		inFlightMetadata := &protos.ViewMetadata{}
468		if err := proto.Unmarshal(inFlight.Metadata, inFlightMetadata); err != nil {
469			v.Logger.Panicf("Node %d is unable to unmarshal its own in flight metadata, err: %v", v.SelfID, err)
470		}
471		proposal := &protos.Proposal{
472			Header:               inFlight.Header,
473			Metadata:             inFlight.Metadata,
474			Payload:              inFlight.Payload,
475			VerificationSequence: uint64(inFlight.VerificationSequence),
476		}
477		if lastDecision == nil {
478			v.Logger.Panicf("%d The given last decision is nil", v.SelfID)
479			return nil
480		}
481		if lastDecision.Metadata == nil {
482			return proposal // this is the first proposal after genesis
483		}
484		lastDecisionMetadata := &protos.ViewMetadata{}
485		if err := proto.Unmarshal(lastDecision.Metadata, lastDecisionMetadata); err != nil {
486			v.Logger.Panicf("Node %d is unable to unmarshal its own last decision metadata from checkpoint, err: %v", v.SelfID, err)
487		}
488		if inFlightMetadata.LatestSequence == lastDecisionMetadata.LatestSequence {
489			v.Logger.Debugf("Node %d's in flight proposal and the last decision has the same sequence: %d", v.SelfID, inFlightMetadata.LatestSequence)
490			return nil // this is not an actual in flight proposal
491		}
492		if inFlightMetadata.LatestSequence+1 == lastDecisionMetadata.LatestSequence && v.committedDuringViewChange != nil &&
493			v.committedDuringViewChange.LatestSequence == lastDecisionMetadata.LatestSequence {
494			v.Logger.Infof("Node %d's in flight proposal sequence is %d while already committed decision %d, "+
495				"but that is because it committed it during the view change", v.SelfID, inFlightMetadata.LatestSequence, lastDecisionMetadata.LatestSequence)
496			return nil
497		}
498		return proposal
499	}
500	
501	func (v *ViewChanger) validateViewDataMsg(svd *protos.SignedViewData, sender uint64) bool {
502		if v.getLeader() != v.SelfID { // check if I am the next leader
503			v.Logger.Warnf("Node %d got %s from %d, but %d is not the next leader of view %d", v.SelfID, signedViewDataToString(svd), sender, v.SelfID, v.currView)
504			return false
505		}
506	
507		vd := &protos.ViewData{}
508		if err := proto.Unmarshal(svd.RawViewData, vd); err != nil {
509			v.Logger.Errorf("Node %d was unable to unmarshal viewData message from %d, error: %v", v.SelfID, sender, err)
510			return false
511		}
512		if vd.NextView != v.currView { // check that the message is aligned to this view
513			v.Logger.Warnf("Node %d got %s from %d, but %d is in view %d", v.SelfID, signedViewDataToString(svd), sender, v.SelfID, v.currView)
514			return false
515		}
516	
517		valid, lastDecisionSequence := v.checkLastDecision(svd, sender)
518		if !valid {
519			v.Logger.Warnf("Node %d got %v from %d, but the check of the last decision didn't pass", v.SelfID, signedViewDataToString(svd), sender)
520			return false
521		}
522	
523		v.Logger.Debugf("Node %d got %s from %d, and it passed the last decision check", v.SelfID, signedViewDataToString(svd), sender)
524	
525		if err := ValidateInFlight(vd.InFlightProposal, lastDecisionSequence); err != nil {
526			v.Logger.Warnf("Node %d got %v from %d, but the in flight proposal is invalid, reason: %v", v.SelfID, signedViewDataToString(svd), sender, err)
527			return false
528		}
529	
530		v.Logger.Debugf("Node %d got %s from %d, and the in flight proposal is valid", v.SelfID, signedViewDataToString(svd), sender)
531	
532		return true
533	}
534	
535	func (v *ViewChanger) checkLastDecision(svd *protos.SignedViewData, sender uint64) (valid bool, lastDecisionSequence uint64) {
536		vd := &protos.ViewData{}
537		if err := proto.Unmarshal(svd.RawViewData, vd); err != nil {
538			v.Logger.Errorf("Node %d was unable to unmarshal viewData message from %d, error: %v", v.SelfID, sender, err)
539			return false, 0
540		}
541	
542		if vd.LastDecision == nil {
543			v.Logger.Warnf("Node %d got %s from %d, but the last decision is not set", v.SelfID, signedViewDataToString(svd), sender)
544			return false, 0
545		}
546	
547		mySequence, myLastDecision := v.extractCurrentSequence()
548	
549		// Begin to check the last decision within the view data message.
550		//
551		// The sender might be behind, in which case the new leader might not have the right config to validate
552		// the decision and signatures, and so the view data message is deemed invalid.
553		//
554		// If the sender is too far ahead, the new leader might not have the appropriate config.
555		// We do not want the new leader to perform a sync at this point, since the sender might be malicious.
556		// So this message is considered invalid. If the leader is actually behind this view change will eventually timeout.
557		//
558		// If the new leader and the sender have the same last decision sequence then we check that the decisions are equal.
559		// However, we cannot validate the decision signatures since this last decision might have been a reconfig.
560		//
561		// Lastly, the sender is ahead by one sequence, and so the new leader validates the decision and delivers it.
562		// Only after delivery the message signature is verified, again since this decision might have been a reconfig.
563	
564		if vd.LastDecision.Metadata == nil { // this is a genesis proposal
565			if mySequence > 0 {
566				v.Logger.Debugf("Node %d got %s from %d, but the last decision seq (0) is lower than this node's current sequence %d", v.SelfID, signedViewDataToString(svd), sender, mySequence)
567				return false, 0 // this node is ahead
568			}
569			return true, 0
570		}
571		lastDecisionMD := &protos.ViewMetadata{}
572		if err := proto.Unmarshal(vd.LastDecision.Metadata, lastDecisionMD); err != nil {
573			v.Logger.Warnf("Node %d got %s from %d, but was unable to unmarshal last decision metadata, err: %v", v.SelfID, signedViewDataToString(svd), sender, err)
574			return false, 0
575		}
576		if lastDecisionMD.ViewId >= vd.NextView {
577			v.Logger.Warnf("Node %d got %s from %d, but the last decision view %d is greater or equal to requested next view %d", v.SelfID, signedViewDataToString(svd), sender, lastDecisionMD.ViewId, vd.NextView)
578			return false, 0
579		}
580	
581		v.Logger.Debugf("Node %d got %s from %d, the last decision seq is %d and this node's current sequence is %d", v.SelfID, signedViewDataToString(svd), sender, lastDecisionMD.LatestSequence, mySequence)
582	
583		if lastDecisionMD.LatestSequence > mySequence+1 { // this is a decision in the future, ignoring since the node might not have the right configuration to validate
584			v.Logger.Debugf("Node %d got %s from %d, but the last decision seq %d is greater than this node's current sequence %d", v.SelfID, signedViewDataToString(svd), sender, lastDecisionMD.LatestSequence, mySequence)
585			return false, 0
586		}
587		if lastDecisionMD.LatestSequence < mySequence { // this is a decision in the past, ignoring since the node might not have the right configuration to validate
588			v.Logger.Debugf("Node %d got %s from %d, but the last decision seq %d is lower than this node's current sequence %d", v.SelfID, signedViewDataToString(svd), sender, lastDecisionMD.LatestSequence, mySequence)
589			return false, 0
590		}
591	
592		if lastDecisionMD.LatestSequence == mySequence { // just make sure that we have the same last decision, can't verify the signatures of this last decision since this might have been a reconfiguration
593			// the signature on this message can be verified
594			if svd.Signer != sender {
595				v.Logger.Warnf("Node %d got %s from %d, but signer %d is not the sender %d", v.SelfID, signedViewDataToString(svd), sender, svd.Signer, sender)
596				return false, 0
597			}
598			if err := v.Verifier.VerifySignature(types.Signature{ID: svd.Signer, Value: svd.Signature, Msg: svd.RawViewData}); err != nil {
599				v.Logger.Warnf("Node %d got %s from %d, but signature is invalid, error: %v", v.SelfID, signedViewDataToString(svd), sender, err)
600				return false, 0
601			}
602	
603			// compare the last decision itself
604			if !proto.Equal(vd.LastDecision, myLastDecision) {
605				v.Logger.Warnf("Node %d got %s from %d, they are at the same sequence but the last decisions are not equal", v.SelfID, signedViewDataToString(svd), sender)
606				return false, 0
607			}
608	
609			return true, lastDecisionMD.LatestSequence
610		}
611	
612		if lastDecisionMD.LatestSequence != mySequence+1 {
613			v.Logger.Warnf("Node %d got %s from %d, the last decision sequence is not equal to this node's sequence + 1", v.SelfID, signedViewDataToString(svd), sender)
614			return false, 0
615		}
616	
617		// This node is one sequence behind, validate the last decision and deliver
618	
619		_, err := ValidateLastDecision(vd, v.quorum, v.N, v.Verifier)
620		if err != nil {
621			v.Logger.Warnf("Node %d got %s from %d, but the last decision is invalid, reason: %v", v.SelfID, signedViewDataToString(svd), sender, err)
622			return false, 0
623		}
624	
625		proposal := types.Proposal{
626			Header:               vd.LastDecision.Header,
627			Metadata:             vd.LastDecision.Metadata,
628			Payload:              vd.LastDecision.Payload,
629			VerificationSequence: int64(vd.LastDecision.VerificationSequence),
630		}
631		signatures := make([]types.Signature, 0, len(vd.LastDecisionSignatures))
632		for _, sig := range vd.LastDecisionSignatures {
633			signature := types.Signature{
634				ID:    sig.Signer,
635				Value: sig.Value,
636				Msg:   sig.Msg,
637			}
638			signatures = append(signatures, signature)
639		}
640		v.deliverDecision(proposal, signatures)
641	
642		// Make note that we have advanced the sequence during a view change,
643		// so our in-flight sequence may be behind.
644		md := &protos.ViewMetadata{}
645		if err = proto.Unmarshal(proposal.Metadata, md); err != nil {
646			v.Logger.Panicf("Node %d got %s from %d, but was unable to unmarshal proposal metadata, err: %v", v.SelfID, signedViewDataToString(svd), sender, err)
647		}
648		v.committedDuringViewChange = md
649	
650		select { // if there was a delivery with a reconfig we need to stop here before verify signature
651		case <-v.stopChan:
652			return false, 0
653		default:
654		}
655	
656		if svd.Signer != sender {
657			v.Logger.Warnf("Node %d got %s from %d, but signer %d is not the sender %d", v.SelfID, signedViewDataToString(svd), sender, svd.Signer, sender)
658			return false, 0
659		}
660		if err = v.Verifier.VerifySignature(types.Signature{ID: svd.Signer, Value: svd.Signature, Msg: svd.RawViewData}); err != nil {
661			v.Logger.Warnf("Node %d got %s from %d, but signature is invalid, error: %v", v.SelfID, signedViewDataToString(svd), sender, err)
662			return false, 0
663		}
664	
665		return true, lastDecisionMD.LatestSequence
666	}
