729	// ValidateInFlight validates the given in-flight proposal
730	func ValidateInFlight(inFlightProposal *protos.Proposal, lastSequence uint64) error {
731		if inFlightProposal == nil {
732			return nil
733		}
734		if inFlightProposal.Metadata == nil {
735			return errors.New("in flight proposal metadata is nil")
736		}
737		inFlightMetadata := &protos.ViewMetadata{}
738		if err := proto.Unmarshal(inFlightProposal.Metadata, inFlightMetadata); err != nil {
739			return fmt.Errorf("unable to unmarshal the in flight proposal metadata, err: %w", err)
740		}
741		if inFlightMetadata.LatestSequence != lastSequence+1 {
742			return fmt.Errorf("the in flight proposal sequence is %d while the last decision sequence is %d", inFlightMetadata.LatestSequence, lastSequence)
743		}
744		return nil
745	}
