1338	// Sync calls the synchronizer and informs the view changer of the sync
1339	func (v *ViewChanger) Sync() {
1340		// the in flight proposal view asked to sync
1341		v.Logger.Debugf("Node %d is calling sync because the in flight proposal view has asked to sync", v.SelfID)
1342		v.Synchronizer.Sync()
1343		v.inFlightSyncChan <- struct{}{}
1344	}
