16	
17	// StateCollector collects the current state from other nodes
18	type StateCollector struct {
19		SelfID uint64
20		N      uint64
21		f      int
22		quorum int
23	
24		Logger api.Logger
25	
26		incMsgs chan *incMsg
27	
28		CollectTimeout time.Duration
29	
30		responses *voteSet
31	
32		stopOnce sync.Once
33		stopChan chan struct{}
34	}
35	
36	// Start starts the state collector
37	func (s *StateCollector) Start() {
38		s.incMsgs = make(chan *incMsg, s.N)
39		s.quorum, s.f = computeQuorum(s.N)
40		s.stopChan = make(chan struct{})
41		s.stopOnce = sync.Once{}
42	
43		acceptResponse := func(_ uint64, message *protos.Message) bool {
44			return message.GetStateTransferResponse() != nil
45		}
46		s.responses = &voteSet{
47			validVote: acceptResponse,
48		}
49		s.responses.clear(s.N)
50	}
51	
52	// HandleMessage handle messages addressed to the state collector
53	func (s *StateCollector) HandleMessage(sender uint64, m *protos.Message) {
54		if m.GetStateTransferResponse() == nil {
55			s.Logger.Panicf("Node %d handling a message which is not a response", s.SelfID)
56		}
57		msg := &incMsg{sender: sender, Message: m}
58		s.Logger.Debugf("Node %d handling state response: %v", s.SelfID, msg)
59		select {
60		case <-s.stopChan:
61			return
62		case s.incMsgs <- msg:
63		default: // if incMsgs is full do nothing
64			s.Logger.Debugf("Node %d reached default in handling state response: %v", s.SelfID, msg)
65		}
66	}
67	
68	// ClearCollected clears the responses collected by the state collector
69	func (s *StateCollector) ClearCollected() {
70		// drain message channel
71		for len(s.incMsgs) > 0 {
72			<-s.incMsgs
73		}
74	}
75	
76	// CollectStateResponses return a valid response or nil if reached timeout
77	func (s *StateCollector) CollectStateResponses() *types.ViewAndSeq {
78		s.responses.clear(s.N)
79	
80		timer := time.NewTimer(s.CollectTimeout)
81		defer timer.Stop()
82	
83		s.Logger.Debugf("Node %d started collecting state responses", s.SelfID)
84	
85		for {
86			select {
87			case <-s.stopChan:
88				return nil
89			case <-timer.C:
90				s.Logger.Infof("Node %d reached the state collector timeout", s.SelfID)
91				return nil
92			case msg := <-s.incMsgs:
93				s.Logger.Debugf("Node %d collected a response: %v", s.SelfID, msg)
94				s.responses.registerVote(msg.sender, msg.Message)
95				if viewAndSeq := s.collectedEnoughEqualVotes(); viewAndSeq != nil {
96					s.Logger.Infof("Node %d collected a valid state: view - %d and seq - %d", s.SelfID, viewAndSeq.View, viewAndSeq.Seq)
97					return viewAndSeq
98				}
99			}
100		}
101	}
102	
103	func (s *StateCollector) collectedEnoughEqualVotes() *types.ViewAndSeq {
104		if len(s.responses.voted) <= s.f {
105			return nil
106		}
107		votesMap := make(map[types.ViewAndSeq]uint64)
108		for range len(s.responses.votes) {
109			vote := <-s.responses.votes
110			response := vote.GetStateTransferResponse()
111			if response == nil {
112				s.Logger.Panicf("Node %d collected a message which is not a response", s.SelfID)
113				return nil
114			}
115			viewAndSeq := types.ViewAndSeq{
116				View: response.ViewNum,
117				Seq:  response.Sequence,
118			}
119			s.Logger.Debugf("Node %d collected a responses with view - %d and seq - %d", s.SelfID, viewAndSeq.View, viewAndSeq.Seq)
120			s.responses.votes <- vote
121			votesMap[viewAndSeq]++
122		}
123		for viewAndSeq, count := range votesMap {
124			if count > uint64(s.f) {
125				return &viewAndSeq
126			}
127		}
128		return nil
129	}
130	
131	func (s *StateCollector) close() {
132		s.stopOnce.Do(
133			func() {
134				select {
135				case <-s.stopChan:
136					return
137				default:
138					close(s.stopChan)
139				}
140			},
141		)
142	}
143	
144	// Stop the state collector
145	func (s *StateCollector) Stop() {
146		s.close()
147	}
