324		view.MetricsView.ProposalSequence.Set(float64(view.ProposalSequence))
325		view.MetricsView.DecisionsInView.Set(float64(view.DecisionsInView))
326		view.MetricsView.Phase.Set(float64(view.Phase))
327	
328		return view, view.Phase
